35	/// Renders a `Role::scope_kinds` list as the JSON-array-of-strings the `role.scope_kinds`
36	/// column stores (e.g. `["organization"]`, mirroring the encoding `authz_role_grants.rs`'s
37	/// test fixtures assume) — nothing currently parses this column back at runtime; the
38	/// `role_key -> Role` catalog lookup is always code-defined (`authz::roles::role`), so this
39	/// column is introspectable-only.
40	fn scope_kinds_json(kinds: &[NodeKind]) -> String {
41	    let items: Vec<String> = kinds.iter().map(|k| format!("\"{}\"", node_kind_str(*k))).collect();
42	    format!("[{}]", items.join(","))
43	}
