45	/// Inserts `role_def`'s row if the key is absent; already-present is left untouched
46	/// (idempotent). A unique-constraint violation on insert (a concurrent replica's boot won
47	/// the race between our existence check and our insert) is treated as an idempotent no-op,
48	/// not an error — the row exists either way.
49	async fn seed_role_row(db: &DatabaseConnection, role_def: &Role) -> Result<(), AuthzError> {
50	    if role::Entity::find_by_id(role_def.key.clone()).one(db).await.map_err(map_err)?.is_some() {
51	        return Ok(());
52	    }
53	    let active = role::ActiveModel {
54	        key: Set(role_def.key.clone()),
55	        template_id: Set(role_def.template_id.clone()),
56	        scope_kinds: Set(scope_kinds_json(&role_def.scope_kinds)),
57	        description: Set(if role_def.description.is_empty() { None } else { Some(role_def.description.clone()) }),
58	        system: Set(role_def.system),
59	        created_at: Set(Utc::now()),
60	    };
61	    match active.insert(db).await {
62	        Ok(_) => Ok(()),
63	        Err(e) if matches!(e.sql_err(), Some(SqlErr::UniqueConstraintViolation(_))) => Ok(()),
64	        Err(e) => Err(map_err(e)),
65	    }
66	}
