68	/// Compare-and-warn reconciliation of `authz::roles::starter_policies()` against what's
69	/// currently persisted, then seeds the `role` table from `authz::roles::system_roles()`.
70	/// Policies are reconciled FIRST: every role template's `policy_id == Role::key ==
71	/// Role::template_id` (see `authz::roles` module docs), and `role.template_id` carries an
72	/// FK to `policy.policy_id` (`fk_role_template`) — the referenced policy row must exist
73	/// before the role row can be inserted.
74	pub async fn reconcile_starter(policies: &dyn PolicyStore, db: &DatabaseConnection) -> Result<(), AuthzError> {
75	    let current = policies.list_all().await?;
76	    for doc in authz_roles::starter_policies() {
77	        match current.iter().find(|d| d.policy_id == doc.policy_id) {
78	            None => policies.put(&doc).await?,
79	            Some(existing) if existing.source != doc.source => {
80	                tracing::warn!(
81	                    policy_id = %doc.policy_id,
82	                    "starter policy drift: the stored source differs from the code-defined source; not overwriting a system-owned row"
83	                );
84	            }
85	            Some(_) => {}
86	        }
87	    }
88	
89	    for role_def in authz_roles::system_roles() {
90	        seed_role_row(db, &role_def).await?;
91	    }
92	
93	    Ok(())
94	}
