22	/// Persistence port for authored Cedar policies/templates ([`PolicyDocument`]).
23	#[async_trait]
24	pub trait PolicyStore: Send + Sync {
25	    /// One repeatable-read txn (impl detail) — every document is a consistent snapshot.
26	    async fn list_all(&self) -> Result<Vec<PolicyDocument>, AuthzError>;
27	    /// Validates; rejects system-owned documents.
28	    async fn put(&self, doc: &PolicyDocument) -> Result<(), AuthzError>;
29	    /// Rejects system-owned documents.
30	    async fn delete(&self, policy_id: &str) -> Result<(), AuthzError>;
31	    /// Txn-scoped twin of [`PolicyStore::put`] (SMA-446, Slice B Task B5 — the
32	    /// `PolicyService::put` reference pattern, copying `RoleGrantStore::grant_in`'s posture):
33	    /// validates and writes `doc` on the caller's own `tx`. A same-content unique-violation
34	    /// race absorbs into [`PutOutcome::AbsorbedIdempotent`] via an internal SAVEPOINT (only
35	    /// the savepoint rolls back, never the caller's outer `tx`) rather than the pre-Slice-B
36	    /// posture of aborting the whole transaction and re-reading on a fresh connection; a
37	    /// different-content race still surfaces as `AuthzError::Conflict`. Deliberately never
38	    /// bumps the policy generation counter itself — the caller bumps it once, post-commit,
39	    /// via `PolicyGenBumper`, and only when the outcome is `Inserted`/`Updated` (never for
40	    /// `AbsorbedIdempotent` — the winning writer already bumped it for this row).
41	    async fn put_in(&self, tx: &dyn Transaction, doc: &PolicyDocument) -> Result<PutOutcome, AuthzError>;
42	    /// Txn-scoped twin of [`PolicyStore::delete`]: deletes `policy_id` on the caller's own
43	    /// `tx`, returning whether a row actually existed to delete — mirrors
44	    /// [`RoleGrantStore::revoke_in`]'s idempotent-DELETE posture (the caller only
45	    /// enqueues/records/bumps when this is `true`). Deliberately never bumps the generation
46	    /// counter itself, same reasoning as [`PolicyStore::put_in`].
47	    async fn delete_in(&self, tx: &dyn Transaction, policy_id: &str) -> Result<bool, AuthzError>;
48	    async fn policy_gen(&self) -> Result<u64, AuthzError>;
49	    async fn bump_policy_gen(&self) -> Result<u64, AuthzError>;
50	}
