165	    async fn list_all(&self) -> Result<Vec<PolicyDocument>, AuthzError> {
166	        // REPEATABLE READ: every row this transaction sees is a single consistent snapshot,
167	        // even if a concurrent `put`/`delete` commits mid-read (port doc contract).
168	        let txn = self.db.begin_with_config(Some(IsolationLevel::RepeatableRead), None).await.map_err(map_err)?;
169	        let models = policy::Entity::find().all(&txn).await.map_err(map_err)?;
170	        txn.commit().await.map_err(map_err)?;
171	
172	        models.into_iter().map(model_to_doc).collect()
173	    }
174	
175	    async fn put(&self, doc: &PolicyDocument) -> Result<(), AuthzError> {
176	        // Thin one-shot-`UnitOfWork` wrapper (SMA-446 Slice B Task B5), mirroring
177	        // `PgRoleGrantStore::grant`: open a `SeaOrmTransaction`, drive the write via
178	        // `put_in`, commit, then best-effort bump — skipped entirely when the outcome is an
179	        // idempotent absorb (module docs: the winning writer already bumped for this row).
180	        let txn = self.db.begin().await.map_err(map_err)?;
181	        let tx: Box<dyn Transaction> = Box::new(SeaOrmTransaction { txn });
182	        let outcome = self.put_in(&*tx, doc).await?;
183	        tx.commit().await.map_err(map_txn_err)?;
184	        if !matches!(outcome, PutOutcome::AbsorbedIdempotent) {
185	            self.bump_policy_gen_best_effort().await;
186	        }
187	        Ok(())
188	    }
189	
190	    async fn delete(&self, policy_id: &str) -> Result<(), AuthzError> {
191	        // Thin one-shot-`UnitOfWork` wrapper, mirroring `put` above / `PgRoleGrantStore::
192	        // revoke`.
193	        let txn = self.db.begin().await.map_err(map_err)?;
194	        let tx: Box<dyn Transaction> = Box::new(SeaOrmTransaction { txn });
195	        let existed = self.delete_in(&*tx, policy_id).await?;
196	        tx.commit().await.map_err(map_txn_err)?;
197	        if existed {
198	            self.bump_policy_gen_best_effort().await;
199	        }
200	        Ok(())
201	    }
202	
203	    async fn put_in(&self, tx: &dyn Transaction, doc: &PolicyDocument) -> Result<PutOutcome, AuthzError> {
204	        validate_policy(&doc.source)?;
205	
206	        let txn = recover_txn(tx).map_err(map_txn_err)?;
207	
208	        let existing = policy::Entity::find_by_id(doc.policy_id.clone()).lock_exclusive().one(txn).await.map_err(map_err)?;
209	        if let Some(existing) = &existing
210	            && existing.system
211	        {
212	            return Err(AuthzError::SystemImmutable(doc.policy_id.clone()));
213	        }
214	
215	        // On UPDATE, preserve the stored row's `created_at` — only INSERT takes it from
216	        // `doc` (the row is genuinely new then). This must read the fetched `existing`, not
217	        // `doc.system`/`doc.created_at`, or a caller could silently rewrite history.
218	        match existing {
219	            Some(existing) => {
220	                let active = doc_to_model(doc, existing.created_at);
221	                active.update(txn).await.map_err(map_err)?;
222	                Ok(PutOutcome::Updated)
223	            }
224	            None => {
225	                // Our existence check (`existing == None`) and this INSERT aren't atomic:
226	                // two replicas/callers can both see an absent row and both attempt to insert
227	                // the same `policy_id`. Run the INSERT on a SAVEPOINT — a nested SeaORM
228	                // transaction opened directly off the recovered `&DatabaseTransaction`
229	                // (`TransactionTrait::begin` only needs `&self`, so this works without `&mut`
230	                // on `put_in`'s own `&dyn Transaction` receiver — see the module doc's borrow
231	                // note) — so a unique-constraint violation rolls back only the savepoint, not
232	                // the caller's outer `tx`.
233	                let active = doc_to_model(doc, doc.created_at);
234	                let sp = txn.begin().await.map_err(map_err)?;
235	                match active.insert(&sp).await {
236	                    Ok(_) => {
237	                        sp.commit().await.map_err(map_err)?;
238	                        Ok(PutOutcome::Inserted)
239	                    }
240	                    Err(e) if matches!(e.sql_err(), Some(SqlErr::UniqueConstraintViolation(_))) => {
241	                        // `ROLLBACK TO SAVEPOINT`: discards only the failed INSERT — the
242	                        // caller's outer `tx` stays alive and usable (savepoint isolation).
243	                        sp.rollback().await.map_err(map_err)?;
244	
245	                        // Re-read the row that won the race, WITHIN the same outer UoW txn
246	                        // (no fresh connection needed — the savepoint rollback cleared the
247	                        // abort without touching `txn`), and compare its content to what we
248	                        // tried to write:
249	                        //   - SAME content (the cold-boot `reconcile_starter` race, SMA-444
250	                        //     Task 17, where both replicas race to insert the IDENTICAL
251	                        //     starter policy against a fresh/unseeded DB) — the upsert intent
252	                        //     ("this policy_id is present with this content") is satisfied
253	                        //     either way; absorb it as `PutOutcome::AbsorbedIdempotent`,
254	                        //     mirroring `bootstrap.rs::seed_role_row`'s absorption. The
255	                        //     caller skips its post-commit `policy_gen` bump on this outcome:
256	                        //     the winning writer's own `put`/`put_in` call already bumped it
257	                        //     for this row's creation, so bumping again here would just be a
258	                        //     redundant invalidation signal for a change we didn't make.
259	                        //   - DIFFERENT content (two callers of the public `PutPolicy` API
260	                        //     racing to CREATE the same `policy_id` with different documents)
261	                        //     — the loser's write was silently discarded; that's a lost
262	                        //     update, not an idempotent no-op, so it must be surfaced as a
263	                        //     conflict, never a silent success.
264	                        let winner = policy::Entity::find_by_id(doc.policy_id.clone())
265	                            .one(txn)
266	                            .await
267	                            .map_err(map_err)?
268	                            .ok_or_else(|| backend_err(format!("policy {}: unique-constraint violation on insert but no row found on re-read", doc.policy_id)))?;
269	
270	                        if policy_content_matches(&winner, doc) {
271	                            Ok(PutOutcome::AbsorbedIdempotent)
272	                        } else {
273	                            Err(AuthzError::Conflict(doc.policy_id.clone()))
274	                        }
275	                    }
276	                    // Any OTHER `DbErr` still propagates as `Backend` — only a
277	                    // unique-constraint violation gets the race-absorption treatment above.
278	                    // The failed INSERT aborted only the savepoint (already rolled back
279	                    // implicitly by dropping `sp` here without commit); the outer `tx`
280	                    // remains usable by the caller.
281	                    Err(e) => Err(map_err(e)),
282	                }
283	            }
284	        }
285	    }
