287	    async fn delete_in(&self, tx: &dyn Transaction, policy_id: &str) -> Result<bool, AuthzError> {
288	        let txn = recover_txn(tx).map_err(map_txn_err)?;
289	
290	        let Some(existing) = policy::Entity::find_by_id(policy_id.to_string()).lock_exclusive().one(txn).await.map_err(map_err)? else {
291	            // Idempotent: nothing to delete, nothing to invalidate — mirrors
292	            // `RoleGrantStore::revoke_in`'s posture.
293	            return Ok(false);
294	        };
295	        if existing.system {
296	            return Err(AuthzError::SystemImmutable(policy_id.to_string()));
297	        }
298	
299	        policy::Entity::delete_by_id(policy_id.to_string()).exec(txn).await.map_err(map_err)?;
300	        Ok(true)
301	    }
